# Strava Fitness Tracking API
import requests

STRAVA_CLIENT_ID = "GarminConnectAuthenticationError"
STRAVA_CLIENT_SECRET = "your_secret"
STRAVA_ACCESS_TOKEN = "get_from_oauth"

def get_strava_activities(after_date):
    """Get recent activities from Strava"""
    response = requests.get(
        "https://www.strava.com/api/v3/athlete/activities",
        headers={"Authorization": f"Bearer {STRAVA_ACCESS_TOKEN}"},
        params={"after": after_date, "per_page": 30}
    )
    return response.json()

def get_activity_details(activity_id):
    """Get detailed activity information"""
    response = requests.get(
        f"https://www.strava.com/api/v3/activities/{activity_id}",
        headers={"Authorization": f"Bearer {STRAVA_ACCESS_TOKEN}"}
    )
    return response.json()

def analyze_performance(activities):
    """Analyze performance trends"""
    # Calculate metrics
    total_distance = sum(a.get('distance', 0) for a in activities)
    total_time = sum(a.get('moving_time', 0) for a in activities)
    avg_speed = total_distance / total_time if total_time > 0 else 0

    return {
        "total_distance_km": total_distance / 1000,
        "total_time_hours": total_time / 3600,
        "average_speed_mps": avg_speed,
        "activity_count": len(activities)
    }
